IF DB_ID('findit_db') IS NULL CREATE DATABASE findit_db; GO USE findit_db; GO
IF OBJECT_ID('dbo.Claims','U') IS NOT NULL DROP TABLE dbo.Claims; IF OBJECT_ID('dbo.Items','U') IS NOT NULL DROP TABLE dbo.Items; IF OBJECT_ID('dbo.Users','U') IS NOT NULL DROP TABLE dbo.Users; GO
CREATE TABLE Users(UserId INT IDENTITY PRIMARY KEY,FullName NVARCHAR(100) NOT NULL,Email NVARCHAR(200) NOT NULL UNIQUE,PasswordHash NVARCHAR(300) NOT NULL,Role NVARCHAR(10) NOT NULL CONSTRAINT DF_UserRole DEFAULT 'Student' CHECK(Role IN('Student','Admin')),Phone NVARCHAR(20) NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),IsActive BIT NOT NULL DEFAULT 1);
CREATE TABLE Items(ItemId INT IDENTITY PRIMARY KEY,UserId INT NOT NULL REFERENCES Users(UserId),Title NVARCHAR(120) NOT NULL,Description NVARCHAR(1500) NOT NULL,Category NVARCHAR(40) NOT NULL,ItemType NVARCHAR(5) NOT NULL CHECK(ItemType IN('Lost','Found')),Location NVARCHAR(200) NOT NULL,DateOfIncident DATE NOT NULL,ImagePath NVARCHAR(260) NULL,Status NVARCHAR(10) NOT NULL DEFAULT 'Open' CHECK(Status IN('Open','Claimed','Closed')),CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Claims(ClaimId INT IDENTITY PRIMARY KEY,ItemId INT NOT NULL REFERENCES Items(ItemId),ClaimerId INT NOT NULL REFERENCES Users(UserId),ClaimDescription NVARCHAR(1000) NOT NULL,ClaimStatus NVARCHAR(10) NOT NULL DEFAULT 'Pending' CHECK(ClaimStatus IN('Pending','Approved','Rejected')),AdminRemarks NVARCHAR(1000) NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NULL,CONSTRAINT UQ_Claim_User_Item UNIQUE(ItemId,ClaimerId));
CREATE INDEX IX_Items_Search ON Items(ItemType,Category,Status,DateOfIncident);CREATE INDEX IX_Items_Created ON Items(CreatedAt DESC);CREATE INDEX IX_Claims_Status ON Claims(ClaimStatus,CreatedAt);CREATE INDEX IX_Users_RoleActive ON Users(Role,IsActive);
PRINT 'Database schema created. Register first user then promote to Admin using the safe SQL below.';
